/* ================= LANG =================
   Kaj: page er lekha Bangla/English dictionary onujayi
   bosano (applyLang) — data-i18n thaka prottek lekha bodle jay */

function applyLang(){
  document.documentElement.lang=lang;
  document.documentElement.dir=['ar','ur','fa'].includes(lang)?'rtl':'ltr';
  $$('[data-i18n]').forEach(e=>{if(e.getAttribute&&e.getAttribute('data-dynamic')==='1')return;e.textContent=t(e.dataset.i18n);});
  $$('[data-i18n-ph]').forEach(e=>e.placeholder=t(e.dataset.i18nPh));
  const _lb=$('#langBtn');if(_lb&&_lb.tagName==='SELECT')_lb.value=lang;
}

/* data: WCC -> data-world.js file e sorano hoyeche */
const WCONT_FILL={Asia:'#a9d6b5',Europe:'#a9c6e8',Africa:'#f2d38f',NorthAmerica:'#f2a183',SouthAmerica:'#cdb2e8',Oceania:'#8fd6dd'};
function contFill(name){try{const w=WC.find(x=>x.name===name);return w?WCONT_FILL[w.c]:null;}catch(e){return null;}}

/* ================= MAPPER =================
   Kaj: manchitro engine — map aka, desh/jela click kore
   bachai, zoom/drag, bachai er count ar map download (PNG/PDF) */

const THEMES=[['#0f8a8f','#e5eeed'],['#f2a33a','#f3ebd9'],['#c2417a','#f1e4ea'],['#2e8b57','#e3eee6'],['#4a5bd6','#e5e7f4'],['#1f2933','#e8e8e6']];
function Mapper(cfg){
  const m=Object.assign({sel:new Set(),theme:0,custom:'',you:'',photo:null,showNames:true,feats:[],mode:'tile',items:[],loading:true},cfg);
  const root=$('#'+cfg.id+'-root');
  root.innerHTML=`${cfg.noList?('<div class="wd-names" id="'+cfg.id+'-names"></div>'):''}<div class="panel mapp"><div class="mapcol"><div class="mapbox">${cfg.id==='bd'?('<div class="map-percent" id="'+cfg.id+'-percent">'+num(0)+'%</div>'):''}<div class="wpick-zoom"><button type="button" data-z="in" title="Zoom in">+</button><button type="button" data-z="out" title="Zoom out">−</button><button type="button" data-z="reset" title="Reset zoom">⟲</button></div><svg id="${cfg.id}-svg" role="img"></svg></div><div class="alert alert-info note noprint" id="${cfg.id}-status"></div></div>
  <div class="sidecol"><div class="card shadow-sm noprint"><div class="count" id="${cfg.id}-count"></div>${cfg.id==='bd'?('<label class="f form-check" style="margin-top:8px"><input class="form-check-input" type="checkbox" id="'+cfg.id+'-names" checked> <span id="'+cfg.id+'-namesL"></span></label>'):''}
  <div class="d-flex gap-2 flex-wrap align-items-center"><button class="btn btn-outline-secondary btn-sm" id="${cfg.id}-all" type="button"></button><button class="btn btn-outline-secondary btn-sm" id="${cfg.id}-clear" type="button"></button></div>
  <label class="f form-label fw-semibold" id="${cfg.id}-themeL"></label><div class="swatches" id="${cfg.id}-themes"></div>
  <label class="f form-label fw-semibold" id="${cfg.id}-youL"></label><input class="form-control" type="text" id="${cfg.id}-you" maxlength="40">
  <label class="f form-label fw-semibold" id="${cfg.id}-photoL"></label><input type="file" id="${cfg.id}-photo" accept="image/*">
  <div id="${cfg.id}-fileWrap" class="hidden"><label class="f form-label fw-semibold" id="${cfg.id}-fileL"></label><input type="file" id="${cfg.id}-file" accept=".json,.geojson,application/json"></div>
  </div><div class="dlbar noprint text-center"><label class="f form-label fw-semibold" id="${cfg.id}-dlL"></label><div class="d-flex gap-2 flex-wrap align-items-center justify-content-center"><button class="btn btn-primary btn-sm" data-dl="png" type="button">↓ PNG</button><button class="btn btn-primary btn-sm" data-dl="jpg" type="button">↓ JPG</button><button class="btn btn-primary btn-sm" data-dl="pdf" type="button">↓ PDF</button></div></div></div></div>`;
  const q=s=>$('#'+cfg.id+'-'+s,root);
  m.q=q;
  m.persist=()=>{store.set(cfg.id+'_sel',[...m.sel]);store.set(cfg.id+'_theme',m.theme);store.set(cfg.id+'_custom',m.custom);store.set(cfg.id+'_you',m.you);};
  m.colors=()=>m.custom?[m.custom,'#e8e8e6']:THEMES[m.theme];
  m.toggle=id=>{m.sel.has(id)?m.sel.delete(id):m.sel.add(id);m.persist();m.render();};
  m.labels=()=>{q('themeL').textContent=t('m_theme');q('youL').textContent=t('m_you');q('photoL').textContent=t('m_photo');q('listL').textContent=cfg.id==='bd'?t('m_name'):t('world_h');q('dlL').textContent=t('m_dl');q('tip').textContent=t('m_tip');q('all').textContent=t('m_all');q('clear').textContent=t('m_clear');q('fileL').textContent=t('m_file');q('namesL').textContent=t('m_names');q('search').placeholder=t('search');};
  m.renderThemes=()=>{q('themes').innerHTML=THEMES.map((c,i)=>`<span class="sw ${!m.custom&&m.theme===i?'on':''}" data-i="${i}" style="background:${c[0]}"></span>`).join('')+`<input type="color" id="${cfg.id}-custom" value="${m.custom||'#0f8a8f'}" title="Custom" style="width:34px;height:30px;border:0;padding:0;background:none">`;};
  m.renderList=()=>{
    if(cfg.noList){const nb=q('names');if(nb)nb.innerHTML=m.items.map(it=>'<button type="button" class="btn btn-sm '+(m.sel.has(it.id)?'btn-primary':'btn-outline-secondary')+' wd-name-btn" data-nid="'+esc(it.id)+'">'+esc(wName(it))+'</button>').join('');return;}
    const box=q('list');if(!box||box.classList.contains('form-select'))return;
    let html='',last='';
    m.items.forEach(it=>{
      if(cfg.id==='bd'&&it.div!==last){last=it.div;html+='<div class="dv">'+esc(t('div_'+it.div))+'</div>';}
      html+='<label><input class="form-check-input" type="checkbox" data-id="'+esc(it.id)+'" '+(m.sel.has(it.id)?'checked':'')+'>'+esc(wName(it))+'</label>';
    });
    box.innerHTML=html;
  };
  m.status=()=>{const s=q('status');if(m.loading){s.textContent=t('m_load');s.classList.remove('hidden','warn');}else if(m.mode==='tile'){s.textContent=t(cfg.id==='bd'?'m_fallback':'m_wfallback');s.classList.add('warn');s.classList.remove('hidden');q('fileWrap').classList.remove('hidden');}else if(m.mode==='none'){s.textContent=t('m_nodata');s.classList.add('warn');s.classList.remove('hidden');}else{s.classList.add('hidden');}};
  m.title=()=>(m.you?m.you+' — ':'')+t(cfg.id==='bd'?'bdTitle':'wdTitle');
  m.total=()=>m.items.length;
  m.svgString=(forExport)=>{
    const W=cfg.W,H=cfg.H,[fill,base]=m.colors();let body='';
    const n=[...m.sel].filter(id=>m.items.some(i=>i.id===id)).length;
    const pct=m.total()?Math.round(n/m.total()*100):0;
    if(m.mode==='geo'){
      const fc={type:'FeatureCollection',features:m.feats.map(x=>x.f)};
      const proj=(cfg.id==='bd'?d3.geoMercator():d3.geoNaturalEarth1()).fitExtent([[30,150],[W-30,H-60]],fc);
      const path=d3.geoPath(proj);
      m.feats.forEach(x=>{const on=m.sel.has(x.id);body+=`<path class="reg" data-id="${esc(x.id)}" d="${path(x.f)||''}" fill="${on?fill:base}" stroke="#ff8c1a" stroke-width="${cfg.id==='bd'?1.6:1.1}"/>`;});
      if(m.showNames){m.feats.forEach(x=>{const _on2=m.sel.has(x.id);if(!_on2)return;let c=path.centroid(x.f);if(cfg.id==='bd'&&c&&!isNaN(c[0])){try{const iv=proj.invert(c);if(!(iv&&d3.geoContains&&d3.geoContains(x.f,iv))){const b=path.bounds(x.f);let best=null,bd=-1;for(let i=1;i<12;i++)for(let j=1;j<12;j++){const px=b[0][0]+(b[1][0]-b[0][0])*i/12,py=b[0][1]+(b[1][1]-b[0][1])*j/12;const iv2=proj.invert([px,py]);if(!iv2||!d3.geoContains(x.f,iv2))continue;const d=Math.min(px-b[0][0],b[1][0]-px,py-b[0][1],b[1][1]-py);if(d>bd){bd=d;best=[px,py];}}if(best)c=best;}}catch(e){}}if(isNaN(c[0]))return;const it=m.items.find(i=>i.id===x.id)||{en:x.id,bn:x.id};body+=`<text x="${c[0].toFixed(1)}" y="${c[1].toFixed(1)}" font-size="${_on2?13:(lang==='bn'?8.5:7.5)}" font-weight="${_on2?'800':'400'}" text-anchor="middle" fill="${_on2?'#ffffff':'#173a42'}" stroke="${_on2?'#00000066':'#ffffff88'}" stroke-width=".4" paint-order="stroke" style="pointer-events:none" font-family="Hind Siliguri,sans-serif">${esc(wName(it))}</text>`;});}
    }else if(m.mode==='tile'&&cfg.id==='wd'){
      const cols=14,tw=80,th=26,gx=4,gy=4,x0=(W-(cols*(tw+gx)-gx))/2;
      m.items.forEach((it,i)=>{const on=m.sel.has(it.id);const cx=x0+(i%cols)*(tw+gx),cy=140+Math.floor(i/cols)*(th+gy);const full=wName(it);const nm=full.length>13?full.slice(0,12)+'…':full;
        body+=`<g class="reg" data-id="${esc(it.id)}"><rect x="${cx}" y="${cy}" width="${tw}" height="${th}" rx="5" fill="${on?fill:base}"/><text x="${cx+tw/2}" y="${cy+17}" font-size="9.5" text-anchor="middle" fill="${on?'#fff':'#35505a'}" font-family="Hind Siliguri,sans-serif" style="pointer-events:none">${esc(nm)}</text></g>`;});
    }else if(m.mode==='tile'){
      const colW=(W-80)/2;let col=[150,150];
      DIVS.forEach(([dv,list],di)=>{const c=col[0]<=col[1]?0:1;let y=col[c];const x0=40+c*(colW+0);
        body+=`<text x="${x0}" y="${y+14}" font-size="15" font-weight="700" fill="#0b5d6b" font-family="Hind Siliguri,sans-serif">${esc(t('div_'+dv))}</text>`;y+=24;
        list.forEach(([en,bn],i)=>{const id=key(en),on=m.sel.has(id);const cx=x0+(i%3)*(colW/3),cy=y+Math.floor(i/3)*34;
          body+=`<g class="reg" data-id="${id}"><rect x="${cx}" y="${cy}" width="${colW/3-6}" height="28" rx="6" fill="${on?fill:base}"/><text x="${cx+(colW/3-6)/2}" y="${cy+18}" font-size="11.5" text-anchor="middle" fill="${on?'#fff':'#35505a'}" font-family="Hind Siliguri,sans-serif" style="pointer-events:none">${esc(lang==='bn'?bn:en)}</text></g>`;});
        col[c]=y+Math.ceil(list.length/3)*34+16;});
    }
    const photo=m.photo?`<defs><clipPath id="pc"><circle cx="${W-76}" cy="66" r="36"/></clipPath></defs><image href="${m.photo}" x="${W-112}" y="30" width="72" height="72" preserveAspectRatio="xMidYMid slice" clip-path="url(#pc)"/><circle cx="${W-76}" cy="66" r="36" fill="none" stroke="${fill}" stroke-width="3"/>`:'';
    const unit=cfg.id==='bd'?t('distr'):t('countries');
    const _isBd=cfg.id==='bd';const _youTxt=_isBd&&m.you&&String(m.you).trim()?String(m.you).trim():'';const _titleTxt=_isBd?t('bdTitle'):m.title();const _youLine=_youTxt?`<text x="${W/2}" y="30" font-size="22" font-weight="800" text-anchor="middle" fill="#10292e" font-family="Hind Siliguri,sans-serif">${esc(_youTxt)}</text>`:'';
    return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${W} ${H}" width="${W}" height="${H}">${forExport||true?`<rect width="${W}" height="${H}" fill="#fbfaf6"/>`:''}${photo}
${_youLine}<text x="${W/2}" y="${_isBd?(_youTxt?62:44):62}" text-anchor="middle" font-size="34" font-weight="800" fill="#10292e" font-family="Fraunces,Hind Siliguri,serif">${esc(_titleTxt)}</text>
<text x="${W/2}" y="${_isBd?(_youTxt?90:72):98}" text-anchor="middle" font-size="18" fill="${fill}" font-weight="700" font-family="Hind Siliguri,sans-serif">${num(n)}${esc(t('of'))}${num(m.total())} ${esc(unit)} · ${num(pct)}%</text>${body}
<text x="${W/2}" y="${H-22}" font-size="14" text-anchor="middle" fill="#7a8f93" font-family="Hind Siliguri,sans-serif">World Tour Guide</text></svg>`;
  };
  m.render=()=>{
    q('svg').outerHTML=m.svgString(false).replace('<svg ','<svg id="'+cfg.id+'-svg" ');
    if(m.vb){const _ns=q('svg');if(_ns)_ns.setAttribute('viewBox',m.vb.x+' '+m.vb.y+' '+m.vb.w+' '+m.vb.h);}
    const n=[...m.sel].filter(id=>m.items.some(i=>i.id===id)).length;
    const pct2=m.total()?Math.round(n/m.total()*100):0;
    q('count').textContent=cfg.id==='bd'?(num(n)+' / '+num(m.total())+' · '+num(pct2)+'%'):(num(n)+' / '+num(m.total()));
    const _pctEl=q('percent');if(_pctEl)_pctEl.textContent=num(pct2)+'%';
    m.renderList();m.status();
    if(typeof m.onChange==='function')m.onChange();
  };
  if(cfg.noList){try{['listL','list','tip'].forEach(k=>{const el=q(k);if(el&&el.remove)el.remove();});}catch(e){}}
  m.refreshAll=()=>{m.labels();m.renderThemes();m.render();};
  // zoom & pan for this map
  m.vb=null;
  const _applyVB=()=>{const _s=q('svg');if(_s&&m.vb)_s.setAttribute('viewBox',m.vb.x+' '+m.vb.y+' '+m.vb.w+' '+m.vb.h);};
  m._zoomBy=(f,cx,cy)=>{const _s=q('svg');if(!_s)return;if(!m.vb)m.vb={x:0,y:0,w:cfg.W,h:cfg.H};const vb=m.vb;const nw=Math.min(cfg.W,Math.max(cfg.W/8,vb.w*f));const nh=nw*cfg.H/cfg.W;vb.x=Math.min(Math.max(vb.x+(vb.w-nw)*(cx==null?.5:cx),0),cfg.W-nw);vb.y=Math.min(Math.max(vb.y+(vb.h-nh)*(cy==null?.5:cy),0),cfg.H-nh);vb.w=nw;vb.h=nh;_applyVB();};
  m._zoomReset=()=>{m.vb=null;const _s=q('svg');if(_s)_s.setAttribute('viewBox','0 0 '+cfg.W+' '+cfg.H);};
  root.addEventListener('wheel',e=>{const _sv=e.target.closest&&e.target.closest('svg');if(!_sv||_sv.id!==cfg.id+'-svg')return;e.preventDefault();m._zoomBy(e.deltaY<0?.8:1.25,.5,.5);},{passive:false});
  let _dg=null;
  root.addEventListener('pointerdown',e=>{const _sv=e.target.closest&&e.target.closest('svg');if(!_sv||_sv.id!==cfg.id+'-svg')return;_dg={x:e.clientX,y:e.clientY,moved:0};});
  window.addEventListener('pointermove',e=>{if(!_dg||!m.vb&&_dg.moved===0&&Math.hypot(e.clientX-_dg.x,e.clientY-_dg.y)<=5)return;if(!_dg)return;const _dx=e.clientX-_dg.x,_dy=e.clientY-_dg.y;if(Math.hypot(_dx,_dy)>5)_dg.moved=1;if(_dg.moved&&m.vb){const _s=q('svg');if(_s){const _r=_s.getBoundingClientRect();const _sc=m.vb.w/Math.max(1,_r.width);m.vb.x=Math.min(Math.max(m.vb.x-_dx*_sc,0),cfg.W-m.vb.w);m.vb.y=Math.min(Math.max(m.vb.y-_dy*_sc,0),cfg.H-m.vb.h);_applyVB();}_dg.x=e.clientX;_dg.y=e.clientY;}});
  window.addEventListener('pointerup',()=>{if(_dg&&_dg.moved)m._dragged=true;_dg=null;});

  // events
  root.addEventListener('click',e=>{
    if(m._dragged){m._dragged=false;return;}
    const _nb=e.target.closest&&e.target.closest('[data-nid]');if(_nb){m.toggle(_nb.dataset.nid);return;}
    const _zb=e.target.closest&&e.target.closest('[data-z]');if(_zb){if(_zb.dataset.z==='in')m._zoomBy(.7);else if(_zb.dataset.z==='out')m._zoomBy(1.4);else m._zoomReset();return;}
    const sw=e.target.closest('.sw');if(sw){m.theme=+sw.dataset.i;m.custom='';m.persist();m.renderThemes();m.render();return;}
    const reg=e.target.closest('.reg');if(reg){m.toggle(reg.dataset.id);return;}
    const dl=e.target.closest('[data-dl]');if(dl){m.download(dl.dataset.dl);}
  });
  root.addEventListener('change',e=>{
    if(e.target.matches('input[type=checkbox][data-id]')){m.toggle(e.target.dataset.id);}
    else if(e.target.id===cfg.id+'-list'&&e.target.value){const _v=e.target.value;m.toggle(_v);}
    else if(e.target.id===cfg.id+'-custom'){m.custom=e.target.value;m.persist();m.renderThemes();m.render();}
    else if(e.target.id===cfg.id+'-names'){m.showNames=e.target.checked;m.render();}
    else if(e.target.id===cfg.id+'-photo'){const f=e.target.files[0];if(!f)return;const r=new FileReader();r.onload=()=>{const im=new Image();im.onload=()=>{const c=document.createElement('canvas');c.width=c.height=240;const x=c.getContext('2d');const s=Math.min(im.width,im.height);x.drawImage(im,(im.width-s)/2,(im.height-s)/2,s,s,0,0,240,240);m.photo=c.toDataURL('image/jpeg',.85);m.render();};im.src=r.result;};r.readAsDataURL(f);}
    else if(e.target.id===cfg.id+'-file'&&cfg.onFile){const f=e.target.files[0];if(!f)return;f.text().then(tx=>cfg.onFile(m,JSON.parse(tx))).catch(()=>alert('Invalid file'));}
  });
  q('all').addEventListener('click',()=>{m.items.forEach(i=>m.sel.add(i.id));m.persist();m.render();});
  q('clear').addEventListener('click',()=>{m.sel.clear();m.persist();m.render();});
  q('search').addEventListener('input',m.renderList);
  q('you').value=m.you;q('you').addEventListener('input',e=>{m.you=e.target.value;m.persist();m.render();});
  m.download=async function(type){
    const svg=m.svgString(true);const W=cfg.W,H=cfg.H,sc=2;
    const img=new Image();const url='data:image/svg+xml;charset=utf-8,'+encodeURIComponent(svg);
    await new Promise((res,rej)=>{img.onload=res;img.onerror=rej;img.src=url;}).catch(()=>{alert('Export failed');});
    const c=document.createElement('canvas');c.width=W*sc;c.height=H*sc;const x=c.getContext('2d');x.fillStyle='#fbfaf6';x.fillRect(0,0,c.width,c.height);x.drawImage(img,0,0,c.width,c.height);
    const fn='world-tour-guide-'+cfg.id;
    const save=(href,ext)=>{const a=document.createElement('a');a.href=href;a.download=fn+'.'+ext;document.body.appendChild(a);a.click();a.remove();};
    if(type==='png')c.toBlob(b=>save(URL.createObjectURL(b),'png'));
    else if(type==='jpg')save(c.toDataURL('image/jpeg',.92),'jpg');
    else if(type==='pdf'){if(!(window.jspdf&&window.jspdf.jsPDF))await loadJsPdf();if(window.jspdf&&window.jspdf.jsPDF){const pdf=new window.jspdf.jsPDF({orientation:W>H?'l':'p',unit:'px',format:[W,H]});pdf.addImage(c.toDataURL('image/jpeg',.95),'JPEG',0,0,W,H);pdf.save(fn+'.pdf');}else alert('PDF library not loaded');}
  };
  return m;
}


/* ================= GEO LOADING =================
   Kaj: boundary data load kore site er jela/desher namer
   sathe milano (matchBD, useBDFeatures, useWorldFeatures) */

async function fetchJSON(u){const r=await fetch(u);if(!r.ok)throw new Error(u);return r.json();}
function toFeatures(j){
  if(j&&j.type==='Topology'&&window.topojson){const k=Object.keys(j.objects)[0];return topojson.feature(j,j.objects[k]).features;}
  if(j&&j.type==='FeatureCollection')return j.features;
  if(j&&j.type==='Feature')return [j];
  throw new Error('bad geo');
}
function matchBD(f){const p=f.properties||{};for(const v of Object.values(p)){if(typeof v==='string'){const k=key(v);if(DK[k])return k;}}return null;}
function ringCW(r){let a=0;for(let i=0,n=r.length-1;i<n;i++)a+=(r[i+1][0]-r[i][0])*(r[i+1][1]+r[i][1]);return a>0;}
function rewind(g){ // d3 wants clockwise exterior rings and counter-clockwise holes
  const fix=poly=>poly.map((r,i)=>(i===0)===ringCW(r)?r:r.slice().reverse());
  if(!g)return;if(g.type==='Polygon')g.coordinates=fix(g.coordinates);else if(g.type==='MultiPolygon')g.coordinates=g.coordinates.map(fix);
}
function useBDFeatures(m,features){
  features.forEach(f=>rewind(f.geometry));
  const out=[];const seen=new Set();
  features.forEach(f=>{const id=matchBD(f);if(id&&!seen.has(id)){seen.add(id);out.push({id,f});}});
  if(out.length<50)return false;
  m.feats=out;m.mode='geo';
  m.cent={};out.forEach(x=>{m.cent[x.id]=d3.geoCentroid(x.f);});
  return true;
}

function wname(f){const p=f.properties||{};return p.name||p.NAME||p.ADMIN||p.shapeName||p.name_en||p.NAME_EN||p.COUNTRY||p.country||p.sovereignt||null;}
function useWorldFeatures(m,features,doRewind){
  const fs=features.filter(f=>f.geometry&&wname(f)&&wname(f)!=='Antarctica');
  if(fs.length<100)return false;
  if(doRewind)fs.forEach(f=>rewind(f.geometry));
  m.feats=fs.map(f=>({id:wname(f),f}));
  m.items=m.feats.map(x=>({id:x.id,en:x.id,bn:(x.f.properties&&x.f.properties.NAME_BN)||wBn(x.id)})).sort((a,b)=>a.en.localeCompare(b.en));
  m.mode='geo';return true;
}

/* ================= BUILD MAPS =================
   Kaj: duita map toiri — Bangladesh jela map (bd) ar bishwer
   map (wd); tar agey banner (applyBanners) ar notice bar
   (applyNotice) bosano hoy */

let bd,wd;
function applyBanners(){try{const b=store.get('banners',{});if(!b||!Object.keys(b).length)return;const sel={index:'.pbanner.b-explore',world:'.wbanner',map:'.hero#top',quiz:'.pbanner.b-quiz',places:'.pbanner.b-places',news:'.pbanner.b-news',help:'.pbanner.b-help'};for(const k in sel){if(b[k]){const el=document.querySelector(sel[k]);if(el)el.style.backgroundImage='linear-gradient(rgba(7,52,61,.55),rgba(7,52,61,.55)),url("'+String(b[k]).replace(/"/g,'')+'")';}}}catch(e){}}
function applyNotice(){try{const v=String(store.get('notice','')||'').trim();const bar=document.getElementById('noticeBar'),tx=document.getElementById('noticeText');if(!bar)return;if(v){if(tx)tx.textContent='📢 '+v;bar.hidden=false;}else bar.hidden=true;}catch(e){}}
function applyAds(){try{const a=store.get('ad',{});const media=a?(a.media||a.img||''):'';const type=(a&&a.type)||'img';document.querySelectorAll('[data-adslot]').forEach(el=>{if(media){if(type==='video'){el.innerHTML='<video src="'+esc(media)+'" autoplay muted loop playsinline></video>';}else{el.innerHTML=(a.link?'<a href="'+esc(safeUrl(a.link))+'" target="_blank" rel="noopener sponsored"><img src="'+esc(media)+'" alt=""></a>':'<img src="'+esc(media)+'" alt="">');}el.classList.add('hasad');}else{el.innerHTML='';el.classList.remove('hasad');}});}catch(e){}}


/* ================= FIREBASE CLOUD =================
   Kaj: online database (Firebase) er sathe jogajog —
   cloudPull: database theke place/quiz/news/banner/notice ene
   browser er cache (localStorage) e rakhe, jate ager sob
   render function ager motoi kaj kore;
   cloudPut/cloudDel: admin er jog/muchha database e pathay;
   migrateLocalToCloud: prothom Firebase login e purano local
   data auto database e tule dey (matro ekbar) */

let FDB=null,FAUTH=null,FBOK=false,_cloudReqs=null;
try{ if(window.firebase&&window.WTG_FB){ firebase.initializeApp(window.WTG_FB); FDB=firebase.firestore(); try{FAUTH=firebase.auth();}catch(e){} FBOK=true; } }catch(e){}
function stripFid(o){const c=Object.assign({},o);delete c._fid;return c;}
function imgShrink(src,mx,q){return new Promise(res=>{const im=new Image();im.onload=()=>{let w=im.width,h=im.height;if(w>mx){h=Math.round(h*mx/w);w=mx;}const c=document.createElement('canvas');c.width=w;c.height=h;c.getContext('2d').drawImage(im,0,0,w,h);res(c.toDataURL('image/jpeg',q));};im.onerror=()=>res(src);im.src=src;});}
async function cloudPut(coll,id,data){if(!FBOK||!id)return false;try{await FDB.collection(coll).doc(String(id)).set(data);return true;}catch(e){return false;}}
async function cloudDel(coll,id){if(!FBOK||!id)return;try{await FDB.collection(coll).doc(String(id)).delete();}catch(e){}}

/* Kaj: QUOTA-SAFE place read — puro 'places' collection ar kokhono
   ekbare tana hobe na. cloudPull ekhon sudhu quiz/news/settings tane;
   visitor/admin er je shohorer place dorkar, ei function diye sudhu
   sei shohorer doc gulai ana hoy. city = single-field filter
   (Firestore e notun composite index lagbe na); country
   client-side e miliye neya hoy (eki namer shohor onno deshe
   thakte pare). World-phase e 3000+ doc holeo ekta city view
   tokhon sudhu oi shohorer koyekta read khoroch korbe. */
async function cloudPlacesBy(city,country){
  if(!FBOK||!city)return[];
  try{
    const sn=await FDB.collection('places').where('city','==',String(city)).get();
    return sn.docs.map(d=>Object.assign({},d.data(),{_fid:d.id})).filter(x=>!country||x.country===country);
  }catch(e){return[];}
}

/* Kaj: PDF library (jspdf, 356KB) sudhu PDF download chaplei
   load hoy — page kholar somoy ojotha vajon lage na */
let _pdfP=null;
function loadJsPdf(){if(window.jspdf&&window.jspdf.jsPDF)return Promise.resolve(true);if(_pdfP)return _pdfP;_pdfP=new Promise(res=>{const sc=document.createElement('script');sc.src='jspdf.umd.min.js';sc.onload=()=>res(true);sc.onerror=()=>res(false);document.head.appendChild(sc);});return _pdfP;}
async function cloudPull(){
  if(!FBOK)return;
  try{
    /* NOTE (quota-safe): 'places' collection ekhane ar tana hoy na.
       Prottek page load e puro collection porle (~230 read ekhon,
       world-phase e hajar-hajar) daily 50K read quota more jeto —
       gotokal etai hoyeche. Place ekhon dorkar-onujayi
       cloudPlacesBy(city,country) diye sudhu oi shohorer gulai ana hoy. */
    const [qz,nw,st]=await Promise.all([FDB.collection('quiz').get(),FDB.collection('news').get(),FDB.collection('settings').get()]);
    const applyColl=(snap,key,flag)=>{if(snap.docs.length){const cloud=snap.docs.map(d=>Object.assign({},d.data(),{_fid:d.id}));const ids=new Set(cloud.map(x=>String(x._fid||x.id)));const extra=(store.get(key,[])||[]).filter(x=>!ids.has(String(x._fid||x.id)));store.set(key,cloud.concat(extra));store.set(flag,1);}else if(store.get(flag,0)){if(!(store.get(key,[])||[]).length)store.set(key,[]);}};
    applyColl(qz,'quiz_custom','cloud_on_quiz');
    applyColl(nw,'news','cloud_on_news');
    st.docs.forEach(d=>{const v=d.data()||{};if(d.id==='banners')store.set('banners',v.data||{});if(d.id==='notice')store.set('notice',typeof v.text==='string'?v.text:'');if(d.id==='ad')store.set('ad',v.data||{});});
    applyBanners();applyNotice();applyAds();
    try{if(document.getElementById('tpIdxGrid')&&typeof wpIdxPlaces==='function'&&wpCountry&&wpCity)wpIdxPlaces();}catch(e){}
    try{if(document.getElementById('cityPlaces')&&typeof initCityPage==='function'){_tpInit=false;initCityPage();}}catch(e){}
    if(document.getElementById('newsAdminGrid'))renderAdminNews();
  }catch(e){}
}
async function migrateLocalToCloud(){
  if(!FBOK||store.get('migrated_v1',0))return;
  try{
    const up=async(coll,key,pfx)=>{
      const local=store.get(key,[]);if(!local.length)return;
      const snap=await FDB.collection(coll).limit(1).get();if(!snap.empty)return;
      for(const it of local){const id=it._fid||it.id||(pfx+Date.now()+Math.floor(Math.random()*1e5));await FDB.collection(coll).doc(String(id)).set(stripFid(Object.assign({},it,{id:it.id||id})));}
    };
    await up('places','places_custom','c');
    await up('quiz','quiz_custom','q');
    await up('news','news','n');
    const gems=store.get('gems',[]);
    if(gems.length){const sn=await FDB.collection('requests').get();if(sn.empty){for(const g of gems)await FDB.collection('requests').add(g);}}
    const sb=await FDB.collection('settings').doc('banners').get();const lb=store.get('banners',{});
    if(!sb.exists&&lb&&Object.keys(lb).length)await FDB.collection('settings').doc('banners').set({data:lb});
    const sn2=await FDB.collection('settings').doc('notice').get();const ln=String(store.get('notice','')||'');
    if(!sn2.exists&&ln)await FDB.collection('settings').doc('notice').set({text:ln});
    store.set('migrated_v1',1);
    cloudPull();
  }catch(e){}
}

