    // geoBoundaries rings are CCW; d3 spherical paths need CW exteriors. If not rewound, each district is treated as the rest of the sphere and paints/covers the whole map.
    const _rwFC=function(fc){if(!fc||fc._rw)return;fc._rw=1;const _ra=function(r){if(!r||r.length<4)return 0;let a=0;for(let i=0;i<r.length-1;i++){let x1=r[i][0],y1=r[i][1],x2=r[i+1][0],y2=r[i+1][1];const dx=x2-x1;if(dx>180)x2-=360;else if(dx<-180)x2+=360;a+=x1*y2-x2*y1;}return a/2;};(fc.features||[]).forEach(function(ft){const g=ft&&ft.geometry;if(!g)return;const _clean=function(poly){if(!poly||!poly.length)return null;const ext=poly[0];if(!ext||ext.length<4||Math.abs(_ra(ext))<1e-12)return null;const out=[ext];for(let h=1;h<poly.length;h++){const ring=poly[h];if(ring&&ring.length>=4&&Math.abs(_ra(ring))>=1e-12)out.push(ring);}out.forEach(function(ring,ix){const a=_ra(ring);if((ix===0&&a>0)||(ix>0&&a<0))ring.reverse();});return out;};if(g.type==='Polygon'){const c=_clean(g.coordinates);if(c)g.coordinates=c;else{g.type='MultiPolygon';g.coordinates=[];}}else if(g.type==='MultiPolygon'){g.coordinates=g.coordinates.map(_clean).filter(Boolean);}});};
    if(gb){_rwFC(gb.a1);_rwFC(gb.a2);}
    const adm1=(gb&&gb.a1&&gb.a1.features)||[];
