function bnWord(w){
  let x=w.toLowerCase();
  const SUF=[['ville','ভিল'],['burgh','বার্গ'],['burg','বার্গ'],['berg','বার্গ'],['land','ল্যান্ড'],['mouth','মাউথ'],['ford','ফোর্ড'],['stan','স্তান'],['ton','টন'],['ia','ইয়া']];
  for(const [suf,bn] of SUF){if(x.length>suf.length+1&&x.endsWith(suf))return bnWord(x.slice(0,-suf.length))+bn;}
  const V={a:'আ',e:'এ',i:'ই',o:'ও',u:'উ'},VK={a:'া',e:'ে',i:'ি',o:'ো',u:'ু'};
  const C={b:'ব',c:'ক',d:'দ',f:'ফ',g:'গ',h:'হ',j:'জ',k:'ক',l:'ল',m:'ম',n:'ন',p:'প',q:'ক',r:'র',s:'স',t:'ত',v:'ভ',w:'ও',x:'ক্স',y:'য়',z:'জ'};
  let out='',i=0,start=true;
  const DIG={ch:'চ',sh:'শ',kh:'খ',gh:'ঘ',ph:'ফ',th:'থ',dh:'ধ',bh:'ভ',jh:'ঝ',ng:'ং'};
  while(i<x.length){
    if(x.substr(i,3)==='tch'){out+='চ';i+=3;start=false;continue;}
    const two=x.substr(i,2);
    if(DIG[two]){out+=DIG[two];i+=2;start=false;continue;}
    if(two==='ai'){out+=start?'আই':'াই';i+=2;start=false;continue;}
    if(two==='au'||two==='aw'||two==='ou'){out+=start?'আউ':'াউ';i+=2;start=false;continue;}
    if(two==='oo'){out+=start?'উ':'ু';i+=2;start=false;continue;}
    if(two==='ee'){out+=start?'ঈ':'ী';i+=2;start=false;continue;}
    if(two==='ea'){out+=start?'ই':'ি';i+=2;start=false;continue;}
    if(two==='ei'){out+=start?'এই':'েই';i+=2;start=false;continue;}
    if(two==='oi'){out+=start?'ঐ':'োই';i+=2;start=false;continue;}
    const ch=x[i];
    if('aeiou'.includes(ch)){
      if(ch==='e'&&i===x.length-1&&x.length>2){i++;continue;}
      out+=start?V[ch]:VK[ch];start=false;i++;continue;
    }
    if(ch==='c'&&'eiy'.includes(x[i+1]||'')){out+='স';i++;start=false;continue;}
    if(ch==='g'&&'ei'.includes(x[i+1]||'')){out+='জ';i++;start=false;continue;}
    if(ch==='y'){out+=(start?'ই':'ি');i++;start=false;continue;}
    out+=C[ch]||ch;i++;start=false;
  }
  return out;
}
function bnTranslit(s){if(!s||/[^\x00-\x7F]/.test(s))return s;return s.split(/(\s+|[-'])/).map(w=>/^[A-Za-z]+$/.test(w)?bnWord(w):w).join('');}

function cName(s){return (typeof lang!=='undefined'&&lang==='bn')?(WBC[s]||(typeof WBC2!=='undefined'&&WBC2[s])||bnTranslit(s)):s;}
