/* ================= QUIZ =================
   Kaj: quiz khela — 20 ta proshno ultapalta sajano, uttor
   jachai, score/streak, result ar certificate toiri o download */

const quiz={i:0,score:0,qs:[],done:false,started:false,streak:0,bestStreak:0,cert:{nam:'',country:'',pass:'',add:''}};
/* In-quiz Back handling: the browser Back button moves between quiz screens
   (result/questions -> intro) instead of jumping straight out to the previous page. */
let _qzPopping=false;
function _qzPhase(){return quiz.done?'result':(quiz.started?'play':'intro');}
function _qzHistSync(){
  if(_qzPopping||!document.getElementById('quizBox'))return;
  try{
    const ph=_qzPhase(),cur=history.state&&history.state.qz;
    if(cur===ph)return;
    if(ph==='play'&&cur==='result')history.replaceState({qz:'play'},'');
    else if(cur)history.pushState({qz:ph},'');
    else history.replaceState({qz:ph},'');
  }catch(e){}
}
window.addEventListener('popstate',function(e){
  const box=document.getElementById('quizBox');if(!box)return;
  const ph=e.state&&e.state.qz;
  if(!ph)return; /* no quiz state: let the browser leave the page normally */
  _qzPopping=true;
  try{
    if(quiz.started||quiz.done){quiz.started=false;quiz.done=false;quizRender();}
    history.replaceState({qz:'intro'},'');
  }catch(_){}
  _qzPopping=false;
});
function shuffle(a){a=a.slice();for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]];}return a;}
function quizStart(){if(!document.getElementById('quizBox'))return;quiz.started=false;quiz.done=false;quizRender();}
function _quizDeal(){quiz.qs=shuffle(QUIZ.concat(store.get('quiz_custom',[]))).slice(0,20).map(q=>{const idx=shuffle(q.o.map((_,k)=>k));return {q:q.q,o:idx.map(k=>q.o[k]),a:idx.indexOf(q.a)};});quiz.i=0;quiz.score=0;quiz.streak=0;quiz.bestStreak=0;quiz.done=false;quiz.started=true;quizRender();}
function quizRender(){if(!document.getElementById('quizBox'))return;
  const box=$('#quizBox'),li=lang==='bn'?0:1,letters=lang==='bn'?['ক','খ','গ','ঘ']:['A','B','C','D'];
  box.style.maxWidth=quiz.done?'1120px':'640px';
  if(!quiz.started){const best=+(store.get('quiz_best',0)||0);
    box.innerHTML=`<div class="qz-intro"><div class="qz-emoji">🧠</div><h2 class="qz-title">${esc(t('quiz_h'))}</h2><p class="qz-lead">${esc(t('quiz_lead'))}</p>${best?`<div class="qz-best">🏅 ${esc(t('qz_best'))}: <b>${num(best)} / ${num(20)}</b></div>`:''}<div class="g-form-head sm"><div class="g-form-emoji">📜</div><div><h2>${esc(t('cert_h'))}</h2><p>${esc(t('cert_lead'))}</p></div></div><div class="qz-form text-start bform">
      <div class="row g-2">
      <div class="col-md-6 g-field"><label class="form-label">${esc(t('f_nam'))}</label><input class="form-control" id="qzF-nam" value="${esc(quiz.cert.nam)}" autocomplete="name"></div>
      <div class="col-md-6 g-field"><label class="form-label">${esc(t('f_country'))}</label><input class="form-control" id="qzF-country" list="qzClist" value="${esc(quiz.cert.country)}"><datalist id="qzClist">${(typeof WC!=='undefined'?WC:[]).map(c=>`<option value="${esc(lang==='bn'?(wBn(c.name)||c.name):c.name)}">`).join('')}</datalist></div>
      <div class="col-md-6 g-field"><label class="form-label">${esc(t('f_pass'))}</label><input class="form-control" id="qzF-pass" value="${esc(quiz.cert.pass)}"></div>
      <div class="col-md-6 g-field"><label class="form-label">${esc(t('f_add'))}</label><input class="form-control" id="qzF-add" value="${esc(quiz.cert.add)}"></div>
      </div></div><button class="btn btn-primary btn-lg qz-start" id="qzStart" type="button">▶ ${esc(t('qz_start'))}</button><div class="qz-keys">⌨️ 1–4 / A–D</div></div>`;
    ['nam','country','pass','add'].forEach(k=>{const inp=document.getElementById('qzF-'+k);if(inp)inp.addEventListener('input',()=>{quiz.cert[k]=inp.value;});});
    $('#qzStart').onclick=_quizDeal;_qzHistSync();return;}
  if(quiz.done){const tot=quiz.qs.length,pct=tot?Math.round(quiz.score/tot*100):0,best=Math.max(+(store.get('quiz_best',0)||0),quiz.score);store.set('quiz_best',best);
    const msg=pct>=80?t('qz_t1'):pct>=60?t('qz_t2'):pct>=40?t('qz_t3'):t('qz_t4');
    box.innerHTML=`<div class="qz-res2"><div class="qz-res2-left"><div class="qz-intro"><div class="qz-ring" style="--p:${pct}"><span>${num(pct)}%</span></div><div class="count">${num(quiz.score)} / ${num(tot)}</div><p class="qz-msg">${esc(msg)}</p><p class="qz-bestline">🏅 ${esc(t('qz_best'))}: <b>${num(best)} / ${num(tot)}</b>${quiz.bestStreak>1?` · 🔥 ${esc(t('qz_streak'))} ${num(quiz.bestStreak)}`:''}</p><div class="qz-actions"><button class="btn btn-primary btn-lg" id="qAgain" type="button">🔄 ${esc(t('again'))}</button><a class="btn btn-outline-primary btn-lg" href="index.html">${esc(t('nav_explore'))}</a></div></div></div>
    <div class="qz-certbox qz-res2-right">    <div id="qzCert" class="qz-cert"></div>
    <div class="qz-actions"><button class="btn btn-success" id="qzDlPng" type="button">⬇ ${esc(t('dl_png'))}</button><button class="btn btn-outline-success" id="qzDlPdf" type="button">⬇ ${esc(t('dl_pdf'))}</button></div></div></div>`;
    $('#qAgain').onclick=_quizDeal;_qzCertBind(box);if(window._qzCeleb)window._qzCeleb();_qzHistSync();return;}
  const q=quiz.qs[quiz.i],pct=Math.round(quiz.i/quiz.qs.length*100);
  box.innerHTML=`<div class="qz-top"><span class="qz-pill">${esc(t('q_of'))} ${num(quiz.i+1)} / ${num(quiz.qs.length)}</span><span class="qz-pill qz-score">⭐ ${num(quiz.score)}</span>${quiz.streak>1?`<span class="qz-pill qz-fire">🔥 ${num(quiz.streak)}</span>`:''}</div><div class="bar qz-bar"><i style="width:${pct}%"></i></div><div class="q qz-q">${esc(q.q[li])}</div><div class="qz-opts">${q.o.map((o,k)=>`<button class="btn opt qz-opt" data-k="${k}" type="button"><span class="qz-key">${letters[k]||k+1}</span><span class="qz-txt">${esc(o[li])}</span></button>`).join('')}</div><div id="qFeed"></div><div id="qNext"></div>`;
  $$('.opt',box).forEach(b=>b.onclick=()=>_quizPick(b));_qzHistSync();
}
function _quizPick(b){const box=$('#quizBox');if(!box||quiz.done||!quiz.qs.length)return;const q=quiz.qs[quiz.i];if(!q||b.disabled)return;const k=+b.dataset.k,li=lang==='bn'?0:1;
  $$('.opt',box).forEach(x=>{x.disabled=true;if(+x.dataset.k===q.a)x.classList.add('ok');});
  const right=k===q.a;if(right){quiz.score++;quiz.streak++;quiz.bestStreak=Math.max(quiz.bestStreak,quiz.streak);}else{quiz.streak=0;b.classList.add('bad');}
  const feed=$('#qFeed');if(feed)feed.innerHTML=right?`<div class="qz-feed ok">${esc(t('qz_ok'))}</div>`:`<div class="qz-feed bad">${esc(t('qz_no'))} ${esc(t('qz_right'))}: <b>${esc(q.o[q.a][li])}</b></div>`;
  const sc=box.querySelector('.qz-score');if(sc)sc.textContent='⭐ '+num(quiz.score);
  const last=quiz.i===quiz.qs.length-1;
  $('#qNext').innerHTML=`<button class="btn btn-primary btn-lg w-100 qz-next" type="button" id="qn">${esc(t(last?'finish':'next'))} →</button>`;
  $('#qn').onclick=()=>{if(last)quiz.done=true;else quiz.i++;quizRender();};
}
