(function(){const ph=document.getElementById('gPhoto'),pv=document.getElementById('gPhotoPrev'),hn=document.querySelector('.g-photo-hint');if(ph&&pv){const showP=()=>{const fs=ph.files?[...ph.files]:[];pv.innerHTML='';if(!fs.length){pv.classList.add('hidden');if(hn)hn.classList.remove('hidden');return;}fs.slice(0,6).forEach(f=>{const im=document.createElement('img');im.alt='';im.src=URL.createObjectURL(f);pv.appendChild(im);});pv.classList.remove('hidden');if(hn)hn.classList.add('hidden');};ph.addEventListener('change',showP);var dz=document.querySelector('.g-photo');if(dz){dz.addEventListener('dragover',function(e){e.preventDefault();dz.classList.add('drag');});dz.addEventListener('dragleave',function(){dz.classList.remove('drag');});dz.addEventListener('drop',function(e){e.preventDefault();dz.classList.remove('drag');if(e.dataTransfer&&e.dataTransfer.files&&e.dataTransfer.files.length){ph.files=e.dataTransfer.files;showP();}});}}const ta=document.querySelector('#gemForm textarea[name=desc]'),gc=document.getElementById('gCount');if(ta&&gc){const up=()=>{const n=wcount(ta.value);gc.textContent=num(n);gc.parentElement.classList.toggle('ok',n>=150);};ta.addEventListener('input',up);up();}})();
$('#gemForm').addEventListener('submit',async e=>{
  e.preventDefault();const fd=Object.fromEntries(new FormData(e.target).entries());delete fd.own;
  const ph=document.getElementById('gPhoto');const files=ph&&ph.files?[...ph.files].slice(0,6):[];
  fd.photo=files.map(f=>f.name).join(', ');
  fd.imgs=[];
  for(const f of files){try{fd.imgs.push(await imgDown(f));}catch(_e){}}
  if(fd.imgs.length)fd.img=fd.imgs[0];
  const msg=$('#gMsg');msg.classList.remove('hidden');
  if(wcount(fd.desc)<150){msg.textContent=t('g_words_need');return;}
  const rec=Object.assign({at:Date.now()},fd);
  if(FBOK){try{await FDB.collection('requests').add(rec);msg.textContent=t('g_ok');}catch(err){const g=store.get('gems',[]);g.push(rec);store.set('gems',g);msg.textContent=t('g_local');}}
  else{const g=store.get('gems',[]);g.push(rec);store.set('gems',g);msg.textContent=t('g_local');}
  e.target.reset();const pv=document.getElementById('gPhotoPrev');if(pv){pv.classList.add('hidden');pv.innerHTML='';}const hn=document.querySelector('.g-photo-hint');if(hn)hn.classList.remove('hidden');const cS=document.getElementById('gCountry');if(cS)cS.dispatchEvent(new Event('change'));
});

