/* ================= CITY TOURIST PLACES =================
   Kaj: bachai kora shohor er tourist place — Wikivoyage /
   Wikipedia theke live tothyo ene card banano; admin er jog
   kora place o ekhane prothome dekhay */

var _tpInit=false;
function wtClean(s){return String(s||'').replace(/<!--[\s\S]*?-->/g,'').replace(/\[\[File:[^\]]*\]\]/gi,'').replace(/\[\[[^\]|]*\|([^\]]*)\]\]/g,'$1').replace(/\[\[([^\]]*)\]\]/g,'$1').replace(/\{\{[^{}]*\}\}/g,'').replace(/'''/g,'').replace(/''/g,'').replace(/&mdash;/g,'—').replace(/&ndash;/g,'–').replace(/&amp;/g,'&').replace(/&nbsp;/g,' ').replace(/<[^>]*>/g,'').replace(/\s+/g,' ').replace(/^\*+\s*/,'').trim();}
function wtListings(wt){
  const out=[];let i=0;
  while(i<wt.length){
    const m=/\{\{(see|listing)\b/i.exec(wt.slice(i));if(!m)break;
    const start=i+m.index;let j=start+2,depth=1,end=-1;
    while(j<wt.length){
      if(wt.startsWith('{{',j)){depth++;j+=2;}
      else if(wt.startsWith('}}',j)){depth--;j+=2;if(depth===0){end=j;break;}}
      else j++;
    }
    if(end<0)break;
    const body=wt.slice(start+2,end-2);
    const parts=[];let cur='',d1=0,d2=0;
    for(let k=0;k<body.length;k++){
      const ch=body[k];
      if(ch==='{'&&body[k+1]==='{'){d1++;cur+=ch;continue;}
      if(ch==='}'&&body[k+1]==='}'){d1--;cur+=ch;continue;}
      if(ch==='['&&body[k+1]==='['){d2++;cur+=ch;continue;}
      if(ch===']'&&body[k+1]===']'){d2--;cur+=ch;continue;}
      if(ch==='|'&&d1<=1&&d2===0){parts.push(cur);cur='';continue;}
      cur+=ch;
    }
    parts.push(cur);
    const params={};
    parts.slice(1).forEach(p=>{const eq=p.indexOf('=');if(eq>0)params[p.slice(0,eq).trim()]=p.slice(eq+1).trim();});
    const name=wtClean(params.name||'');
    if(name)out.push({name,desc:wtClean(params.content||''),url:(params.url||'').trim(),img:''});
    i=end;
  }
  return out;
}
function wtBullets(wt){
  const out=[];
  wt.split('\n').forEach(line=>{
    if(!/^\s*\*/.test(line)||line.includes('{{'))return;
    const bm=/'''([^']+)'''/.exec(line);
    if(!bm)return;
    const name=wtClean(bm[1]);
    let desc=wtClean(line.replace(/^\s*\*\s+/,''));
    if(name&&desc.length>30)out.push({name,desc,url:'',img:''});
  });
  return out;
}
async function tpWikivoyage(city){
  try{
    const secs=await fetchJSON('https://en.wikivoyage.org/w/api.php?action=parse&page='+encodeURIComponent(city)+'&prop=sections&format=json&origin=*');
    const list=(secs&&secs.parse&&secs.parse.sections)||[];
    const see=list.find(s=>String(s.line||'').toLowerCase()==='see');
    if(!see)return [];
    const sec=await fetchJSON('https://en.wikivoyage.org/w/api.php?action=parse&page='+encodeURIComponent(city)+'&section='+see.index+'&prop=wikitext&format=json&origin=*');
    const wt=(sec&&sec.parse&&sec.parse.wikitext&&sec.parse.wikitext['*'])||'';
    let entries=wtListings(wt);
    if(entries.length<3)entries=entries.concat(wtBullets(wt));
    const seen=new Set();
    return entries.filter(e=>{const k=e.name.toLowerCase();if(seen.has(k))return false;seen.add(k);return true;}).slice(0,14);
  }catch(e){return [];}
}
async function tpWikiInfo(entries){
  const need=entries.filter(e=>!e.img).slice(0,40);
  if(!need.length)return entries;
  try{
    const titles=need.map(e=>e.name).join('|');
    const d=await fetchJSON('https://en.wikipedia.org/w/api.php?action=query&titles='+encodeURIComponent(titles)+'&prop=pageimages|extracts&exintro&explaintext&exsentences=2&piprop=thumbnail&pithumbsize=500&format=json&origin=*');
    const pages=((d&&d.query&&d.query.pages)||{});
    const byTitle={};
    Object.values(pages).forEach(p=>{byTitle[String(p.title||'').toLowerCase()]=p;});
    const norm={};
    ((d&&d.query&&d.query.normalized)||[]).forEach(n=>{norm[String(n.from||'').toLowerCase()]=String(n.to||'').toLowerCase();});
    entries.forEach(e=>{
      const p=byTitle[e.name.toLowerCase()]||byTitle[norm[e.name.toLowerCase()]||''];
      if(p){
        if(p.thumbnail&&p.thumbnail.source)e.img=p.thumbnail.source;
        if(p.extract&&(!e.desc||e.desc.length<60))e.desc=wtClean(p.extract);
        if(!e.url&&p.title)e.url='https://en.wikipedia.org/wiki/'+encodeURIComponent(p.title.replace(/ /g,'_'));
      }
    });
  }catch(e){}
  return entries;
}
async function tpGeosearch(city,country){
  try{
    let lat=null,lon=null;
    try{
      const cd=await fetchJSON('https://en.wikipedia.org/w/api.php?action=query&generator=search&gsrsearch='+encodeURIComponent(city+' '+country)+'&gsrlimit=3&prop=coordinates&format=json&origin=*');
      const cps=Object.values(((cd&&cd.query&&cd.query.pages)||{}));
      for(const cp of cps){if(cp.coordinates&&cp.coordinates.length){lat=cp.coordinates[0].lat;lon=cp.coordinates[0].lon;break;}}
    }catch(e){}
    if(lat===null){
      const nm=await fetchJSON('https://nominatim.openstreetmap.org/search?format=json&limit=1&q='+encodeURIComponent(city+', '+country));
      if(!nm||!nm.length)return [];
      lat=nm[0].lat;lon=nm[0].lon;
    }
    const d=await fetchJSON('https://en.wikipedia.org/w/api.php?action=query&generator=geosearch&ggscoord='+lat+'%7C'+lon+'&ggsradius=10000&ggslimit=50&prop=pageimages|extracts|categories&exintro&explaintext&exsentences=2&piprop=thumbnail&pithumbsize=500&cllimit=50&clshow=!hidden&format=json&origin=*');
    const pages=Object.values(((d&&d.query&&d.query.pages)||{}));
    const KW=['museum','palace','fort','temple','mosque','church','park','garden','tower','monument','historic','landmark','zoo','lake','beach','archaeolog','heritage','tourist','mausoleum','bazaar','market','observatory','aquarium','waterfall','bridge','library','theatre','theater','gallery','castle','ruins','memorial','shrine','monastery','pagoda','resort','island'];
    const BAD=['railway station','hospital','college','university','school','murder','residence','high commission','embassy','fire','incident','ministry','headquarters','district','division','upazila','thana','corporation','stadium'];
    const score=p=>{
      const title=String(p.title||'');
      const tl=title.toLowerCase();
      const cats=((p.categories||[]).map(c=>c.title||'').join(' ')).toLowerCase();
      let s=0;
      KW.forEach(k=>{if(tl.includes(k))s+=3;if(cats.includes(k))s+=1;});
      BAD.forEach(b=>{if(tl.includes(b))s-=8;});
      if(!p.thumbnail)s-=2;
      if(!p.extract)s-=3;
      if(tl===city.toLowerCase()||tl===country.toLowerCase()||tl.startsWith('tourism in')||tl.startsWith('list of'))s-=20;
      return s;
    };
    return pages.map(p=>({p,s:score(p)})).filter(x=>x.s>=2&&x.p.thumbnail).sort((a,b)=>b.s-a.s).slice(0,10).map(x=>({name:x.p.title,desc:wtClean(x.p.extract||''),url:'https://en.wikipedia.org/wiki/'+encodeURIComponent(String(x.p.title).replace(/ /g,'_')),img:(x.p.thumbnail&&x.p.thumbnail.source)||''}));
  }catch(e){return [];}
}
async function initCityPage(){
  const root=document.getElementById('cityPlaces');if(!root||_tpInit)return;_tpInit=true;
  const params=new URLSearchParams(location.search);
  const city=params.get('city')||'',country=params.get('country')||'';
  const title=document.getElementById('tpTitle'),sub=document.getElementById('tpSub'),status=document.getElementById('tpStatus'),grid=document.getElementById('tpGrid');
  if(title)title.textContent=city||'—';
  if(sub)sub.textContent=(country?country+' · ':'')+t('tp_places_word');
  document.title=(city?city+' — ':'')+'World Tour Guide';
  if(!city){if(status)status.textContent=t('tp_none');return;}
  if(status)status.textContent=t('tp_loading');
  let entries=await tpWikivoyage(city);
  if(entries.length<8){
    const extra=await tpGeosearch(city,country);
    const norm=s=>String(s||'').toLowerCase().replace(/[^a-z0-9]+/g,' ');
    const keys=entries.map(e=>norm(e.name));
    extra.forEach(e=>{
      const k=norm(e.name);
      const dup=keys.some(x=>x&&(k.includes(x)||x.includes(k)));
      if(!dup){entries.push(e);keys.push(k);}
    });
  }
  entries=await tpWikiInfo(entries);
  const _cl0=await cloudPlacesBy(city,country);
  const _seen0=new Set(_cl0.map(x=>String(x._fid||x.id)));
  const _custom=_cl0.concat((store.get('places_custom',[])||[]).filter(x=>x.country===country&&x.city===city&&!_seen0.has(String(x._fid||x.id)))).map(x=>({name:x.name,desc:x.desc||'',img:x.img||'',imgs:(x.imgs&&x.imgs.length?x.imgs:(x.img?[x.img]:[])),who:x.who||'',social:x.social||'',url:x.url||'',custom:true}));
  if(_custom.length){const _ck=new Set(_custom.map(x=>String(x.name||'').toLowerCase()));entries=_custom.concat(entries.filter(e=>!_ck.has(String(e.name||'').toLowerCase())));}
  entries=entries.slice(0,12);
  if(!entries.length){if(status)status.textContent=t('tp_none');return;}
  if(status)status.textContent='';
  if(grid){_tpData=[];_tpData=[];grid.innerHTML=entries.map(tpCardHtml).join('');lzGrid(grid,entries);}
}



