  function admImgDown(f){return new Promise(res=>{const r=new FileReader();r.onload=()=>{const im=new Image();im.onload=()=>{const mx=900;let w=im.width,h=im.height;if(w>mx){h=Math.round(h*mx/w);w=mx;}const c=document.createElement('canvas');c.width=w;c.height=h;c.getContext('2d').drawImage(im,0,0,w,h);res(c.toDataURL('image/jpeg',.72));};im.src=r.result;};r.readAsDataURL(f);});}

