    if(f){if(f.type.indexOf('video/')===0){if(f.size>700*1024){if(m)m.textContent=t('adm_ad_big');return;}const r=new FileReader();r.onload=()=>save(r.result,'video');r.readAsDataURL(f);}else if(f.type==='image/gif'||f.type==='image/svg+xml'){const r=new FileReader();r.onload=()=>save(r.result,'img');r.readAsDataURL(f);}else admImgDown(f).then(d=>save(d,'img'));}
